const hpt = (markup: string, zh: string, meanings = happyPartyTrainMeanings): LyricLine => ({
  words: markup.split("|").map((token) => {
    const jp: Segment[] = [];
    for (const match of token.matchAll(/([\p{Script=Han}々]+)\{([^{}]+)\}|([^{}])/gu)) {
      if (match[1]) jp.push(s(match[1], match[2]));
      else jp.push(s(match[3]));
    }
    const surface = jp.map((part) => part.text).join("").replace(/[\s\p{P}\p{S}]/gu, "");
    const key = jp.map((part) => part.text).join("").trim().replace(/^[（(]|[）)!！?？…、。]+$/g, "");
    const pronunciation = jp.map((part) => part.reading ?? part.text).join("");
    const romaji = surface === "は" ? "wa" : surface === "へ" ? "e" : surface === "を" ? "o"
      : surface === "ポケット" ? "po-ke-tto" : surface === "レール" ? "ree-ru"
      : /^[A-Za-z ]+[！!…]*$/.test(key) ? key.toLowerCase() : romanizeKana(pronunciation);
    const reading = pronunciation.endsWith("っ") ? `${romaji}-t` : romaji;
    const meaning = key === "で" && markup.includes("くちずさん") ? "接续助词" : meanings[key];
    return yw(reading, meaning, ...jp);
  }),
  zh,
});
