  "僕たち":"我们","だけ":"限定助词：只有","新世界":"新世界","（きっと":"（一定","ある）":"存在）","船":"船","往く":"前行、启航","旅立とう":"出发吧","青い":"蔚蓝的","空":"天空","笑ってる":"正微笑着","（なに":"（什么","したい？）":"想做？）",
  "あふれ出して":"满溢而出","もっと":"更加、更远","先":"前方","景色":"风景","望む":"期望、向往","Ah!":"啊！","やっと":"终于","手":"手","した":"做了；手にした：拿到手中","ミライチケット":"未来车票","かざして…！":"高高举起吧……！",
