const soraMorphologyMeanings: Record<string, string> = {
  ...soraKokoroWordMeanings,
  "いか":"进展","なく":"不","て":"接续助词","泣き":"哭泣","そう":"样态助动词：看起来快要……","に":"状态、对象、地点助词","噛み":"咬","つつ":"接续助词：一边……","ん":"说明语气","だ":"判断助动词","繋がり":"相连","で":"而、却","繋がら":"相连","ない":"否定助动词：不","の":"句末说明、疑问语气","よう":"形式名词：仿佛……的样子","語ろ":"诉说","う":"意志、劝诱助动词","走っ":"奔跑","行こ":"前往","し":"做","たく":"想要","なっ":"变得","た":"过去、完成助动词","伝え":"传达、告诉","なくちゃ":"必须……","帰っ":"回去","たら":"条件：……之后、如果……了","動き始め":"开始行动","考え":"思考","も":"也；即使……也","しかた":"办法","迎え":"迎来","てる":"持续、状态","つれ":"带着","くる":"来","呟い":"低语","早め":"稍早、提前","起きよ":"起床","目覚め":"醒来"
};
const sk = (markup: string, zh: string): LyricLine => ({
  words: markup.split("|").map((token) => {
    const jp: Segment[] = [];
    for (const match of token.matchAll(/([\p{Script=Han}々]+)\{([^{}]+)\}|([^{}])/gu)) {
      if (match[1]) jp.push(s(match[1], match[2]));
      else jp.push(s(match[3]));
    }
    const surface = jp.map((part) => part.text).join("").replace(/[\s\p{P}\p{S}]/gu, "");
    const pronunciation = jp.map((part) => part.reading ?? part.text).join("").replace(/[\s\p{P}\p{S}]/gu, "");
    const romaji = surface === "は" ? "wa" : surface === "へ" ? "e" : surface === "を" ? "o"
      : romanizeKana(pronunciation) + (pronunciation.endsWith("っ") ? "-t" : "");
    const meaning = surface === "よ" && markup.includes("あした|よ") ? "呼唤助词：……啊" : soraMorphologyMeanings[surface];
    return yw(romaji, meaning, ...jp);
  }),
  zh,
});

